export type SendEmailBatchInput = {
    /**
     * Up to 100 messages. Their html and text together may hold 10 MiB (413 BATCH_CONTENT_TOO_LARGE).
     */
    emails: Array<BatchSendEmailItem>;
};

export type BatchSendEmailItem = {
    /**
     * An address at a domain verified in this workspace, or at a subdomain of one. Hosted: also any address at the workspace’s built-in domain (connection.builtinDomain in GET /v1/me) until a domain of its own verifies.
     */
    from: string;
    fromName?: string;
    to: string | Array<string>;
    cc?: Array<string>;
    bcc?: Array<string>;
    replyTo?: Array<string>;
    /**
     * Usually omitted: hosted Nightmail sends from the region bound to the sender domain, and a different value fails with SENDER_REGION_MISMATCH. Self-hosted installations default to their default region.
     */
    region?: string;
    /**
     * marketing adds Nightmail's footer (an Unsubscribe link, with the workspace's postal address under it when it has one) and the one-click List-Unsubscribe headers.
     */
    kind?: 'transactional' | 'marketing';
    subject?: string;
    html?: string;
    text?: string;
    /**
     * Uses native SES stored-template rendering and snapshots its rendered MIME. SES does not automatically escape HTML; callers must escape untrusted HTML-context values. Simulated deployments do not render AWS templates.
     */
    template?: {
        name: string;
        /**
         * JSON substitution data, including nested objects and arrays, is passed unchanged to SES. SES stored templates do not automatically escape HTML: callers must escape untrusted values for their HTML context. Maximum serialized JSON length: 262,144 characters.
         */
        data?: {
            [key: string]: unknown;
        };
    };
    /**
     * IDs of files uploaded first (uploadAttachment). One file is at most 8 MiB decoded when sent as base64 in JSON (POST /v1/attachments), or 25 MiB as raw bytes (POST /v1/attachments/upload, with the name URI-encoded in X-Nightmail-Filename and the type in Content-Type). One email carries at most 100 files and 25 MiB of them together, decoded. A workspace keeps at most 100 GiB of uploaded files. For anything larger, link to the file from the email.
     */
    attachments?: Array<string>;
    tracking?: boolean;
    /**
     * Extra MIME headers, 8 KB total. The 15-header limit includes generated headers (two for marketing and any mailbox threading headers). Any name is allowed except headers Nightmail controls: From, Sender, Reply-To, Return-Path, To, Cc, Bcc, Subject, Date, Message-ID, MIME-Version, Content-*, DKIM-*, ARC-*, Authentication-Results, Received*, Resent-*, X-SES-*, List-Unsubscribe*, Auto-Submitted, and reply, receipt, trace and transport headers (Mail-Reply-To, Mail-Followup-To, Followup-To, Disposition-Notification-*, Return-Receipt-To, Errors-To, Bounces-To, Delivered-To, X-Original-To, DomainKey-*, Feedback-ID, TLS-Required, BIMI-*, Autocrypt*, OpenPGP). In-Reply-To and References must be <id@domain> Message-IDs and thread the message in the recipient's mail client.
     */
    headers?: Array<{
        name: string;
        value: string;
    }>;
    /**
     * kind marketing only (422 TOPIC_REQUIRES_MARKETING otherwise): the topic it is about (listTopics). A recipient who opted out of the topic is refused (reason topic_unsubscribed), and its one-click unsubscribe opts out of this topic only.
     */
    topicId?: string;
    /**
     * Request outbound harm screening at accept time for live transactional mail. Hosted live screening is operator-controlled and cannot be disabled by setting this field to false. Simulated mail is not screened. A positive reject verdict fails the request synchronously with 422 CONTENT_REJECTED_SPAM (nothing queued); during a temporary outage of both classifiers, the message is accepted (202) and held unscreened until a classifier answers. Mandatory Hosted screening with no classifier configured returns retryable 503 CONTENT_SCREEN_UNAVAILABLE with Retry-After.
     */
    screen?: boolean;
};

export type EmailPreviews = {
    previews: Array<{
        client: EmailPreviewClient;
        /**
         * Untrusted offline document; render only as the srcdoc of an iframe with sandbox="". Empty for classic Outlook (lint only).
         */
        html: string;
        issues: Array<{
            feature: string;
            clients: Array<EmailPreviewClient>;
            severity: 'warning' | 'error';
        }>;
    }>;
};

export type EmailPreviewClient = 'gmail-web' | 'gmail-ios' | 'gmail-android' | 'gmail-ios-non-google' | 'gmail-android-non-google' | 'apple-mail-macos' | 'apple-mail-ios' | 'outlook-web' | 'outlook-new-windows' | 'outlook-mac' | 'outlook-classic-windows' | 'yahoo-web' | 'aol-web' | 'samsung-email';

/**
 * Supply exactly one source: html or emailId.
 */
export type EmailPreviewInput = {
    /**
     * HTML to preview, up to 256 KiB in UTF-8.
     */
    html: string;
    clients: Array<EmailPreviewClient>;
    theme: 'light' | 'dark';
    /**
     * Viewport width in CSS pixels: mobile 390, desktop 800. Defaults to mobile for iOS, Android and Samsung Email; otherwise desktop.
     */
    device?: 'desktop' | 'mobile';
} | {
    /**
     * Outbound email with retained HTML visible to this credential.
     */
    emailId: string;
    clients: Array<EmailPreviewClient>;
    theme: 'light' | 'dark';
    /**
     * Viewport width in CSS pixels: mobile 390, desktop 800. Defaults to mobile for iOS, Android and Samsung Email; otherwise desktop.
     */
    device?: 'desktop' | 'mobile';
};

export type Email = {
    /**
     * True for replies and older non-campaign mail of unknown origin: the subject or body may contain received content.
     */
    untrustedContent: boolean;
    id: string;
    region: string;
    campaignId: string | null;
    from: string;
    fromName: string | null;
    kind: 'transactional' | 'marketing';
    to: Array<string>;
    cc: Array<string>;
    bcc: Array<string>;
    subject: string;
    /**
     * A scheduled email is queued, with scheduled true, until it is sent at scheduledAt.
     */
    status: 'queued' | 'attempting' | 'accepted' | 'sent' | 'delivered' | 'bounced' | 'complained' | 'rejected' | 'rendering_failed' | 'delayed' | 'suppressed' | 'canceled' | 'acceptance_unknown' | 'simulated';
    providerId: string | null;
    simulated: boolean;
    attemptStartedAt: string | null;
    errorCode: string | null;
    /**
     * Reason recorded when this send was suppressed. For a multi-recipient send blocked locally, this is the first blocked recipient in To, Cc, Bcc order.
     */
    suppressionReason?: string | null;
    /**
     * True while a scheduled send waits for scheduledAt: it has not started sending, and cancelEmail or rescheduleEmail still apply. At that time it is admitted like a send made then (limits and balance included) and follows the usual lifecycle, or is rejected with the refusal’s code.
     */
    scheduled: boolean;
    /**
     * When a scheduled send goes (UTC). Also set while queued mail waits to be retried.
     */
    scheduledAt: string | null;
    /**
     * When the email was submitted; a scheduled send’s moves to the moment it was released at its time.
     */
    createdAt: string;
    updatedAt: string;
};

export type EmailDetail = {
    email: Email;
    content: {
        html: string | null;
        text: string | null;
        attachments: Array<string>;
    };
    events: {
        data: Array<EmailEvent>;
        nextCursor: string | null;
    };
    contact: {
        id: string;
        suppressed: boolean;
        /**
         * When the address was suppressed (UTC). Null when it is not suppressed, and for a suppression from before these dates were kept.
         */
        suppressedAt: string | null;
    } | null;
    thread: EmailThread;
};

export type EmailEvent = {
    id: string;
    emailId: string;
    type: string;
    providerId: string | null;
    simulated: boolean;
    createdAt: string;
    /**
     * What the event recorded. An email the content screen refused says so in code (CONTENT_REJECTED_SPAM) and nothing more: the screen’s score, its model and its threshold are never part of an event or a webhook payload.
     */
    data: {
        /**
         * Reason recorded when this send was suppressed. For a multi-recipient send blocked locally, this is the first blocked recipient in To, Cc, Bcc order.
         */
        suppressionReason?: string;
        /**
         * A bounce or a delay: the receiving server’s reply as SES reported it, such as "smtp; 550 5.1.1 user unknown". Written by the receiving server: untrusted text, to read as data, that can hold the recipient’s address, host names and IP addresses. On the email’s own events (getEmailDetail, listEmailEvents) it is up to 500 characters, as one line without control or invisible characters. In a webhook payload and the webhook delivery log, the addresses and IP addresses in it are replaced by pattern (<address>, <ip>) and it is up to 160 characters. For several recipients, the first that has one. Absent when SES reported none, for a bounce SES generated itself (its suppression list, its address validation), and on events stored before this field.
         */
        diagnosticCode?: string;
        /**
         * A delay: SES’s reason, such as MailboxFull, SpamDetected, RecipientServerError, TransientCommunicationFailure, IPFailure or General.
         */
        delayType?: string;
        /**
         * A delay: when SES stops retrying the delivery (UTC).
         */
        expirationTime?: string;
        [key: string]: unknown;
    };
};

/**
 * The conversation: of a reply from a receiving address or inbox, or of an email whose In-Reply-To named a stored message its sender could read, with the messages around it that you can read. Null for an email in none, when you can read none of the conversation's received or stored messages, and for credentials that cannot read received mail.
 */
export type EmailThread = {
    /**
     * The conversation (getInboundThread).
     */
    id: string;
    /**
     * Messages in it that the caller can read.
     */
    count: number;
    /**
     * Up to 50 of them around this email, oldest first.
     */
    messages: Array<ThreadMessage>;
} | null;

export type ThreadMessage = {
    /**
     * The stored message (getInboundMessage). An email sent with sendEmail that joined the conversation by answering one of its messages has no stored copy: its email ID.
     */
    id: string;
    /**
     * The sent email (getEmailDetail) of an outbound message; null for received mail.
     */
    emailId: string | null;
    direction: 'inbound' | 'outbound';
    from: {
        name: string | null;
        address: string;
    };
    snippet: string;
    /**
     * When it was received or sent.
     */
    at: string;
    /**
     * Received mail: received. Sent mail: the email status (scheduled while it waits for its time).
     */
    status: string;
    attachmentCount: number;
};

export type EmailContent = {
    /**
     * True for replies and older non-campaign mail of unknown origin: the subject or body may contain received content.
     */
    untrustedContent: boolean;
    subject: string;
    html: string | null;
    text: string | null;
    raw: string | null;
    attachments: Array<string>;
    render: 'direct' | 'ses' | 'simulated';
    templateName: string | null;
    simulated: boolean;
};

export type EmailRescheduleInput = {
    /**
     * The new send time: an RFC 3339 instant with Z or an offset, returned in UTC.
     */
    scheduledAt: string;
};

export type Attachment = {
    id: string;
    filename: string;
    contentType: string;
    size: number;
    disposition: 'attachment' | 'inline';
    contentId: string | null;
    createdAt: string;
};

export type AttachmentUpload = {
    filename: string;
    contentType?: string;
    disposition?: 'attachment' | 'inline';
    contentId?: string;
    /**
     * Base64 (standard or URL-safe alphabet; line breaks are accepted). No data URLs. At most 8 MiB decoded in JSON; upload larger files, up to 25 MiB, as raw bytes to POST /v1/attachments/upload.
     */
    content: string;
};

export type AttachmentContent = Attachment & {
    content: string;
};

export type DeletedSendingResource = {
    id: string;
    deleted: true;
};

export type Campaign = {
    id: string;
    /**
     * Dashboard URL for opening this campaign. Drafts open in the editor; launched campaigns open in review.
     */
    url: string;
    revision: number;
    draft: CampaignDraft;
    sourceTemplateId: string | null;
    sourceTemplateRevision: number | null;
    /**
     * draft: editable. preparing: the audience is being frozen (for large lists) and every message is being validated in the background. scheduled: validated and waiting for scheduledAt. sending: recipients are being released into the dispatch queue. paused: releasing stopped by the user or the health check; queued mail still dispatches. done: every recipient was released and dispatched. failed: capture, preparation or releasing failed (delivery.error); edit or launch again. canceled: terminal.
     */
    state: 'draft' | 'preparing' | 'scheduled' | 'sending' | 'paused' | 'done' | 'failed' | 'canceled';
    scheduledAt: string | null;
    archivedAt: string | null;
    createdAt: string;
    updatedAt: string;
    /**
     * Counts of immutable campaign email records grouped by their current status, not cumulative provider events or delivery rates. Drafts with no queued emails have zero counts.
     */
    counts: {
        total: number;
        byStatus: {
            queued?: number;
            attempting?: number;
            accepted?: number;
            sent?: number;
            delivered?: number;
            bounced?: number;
            complained?: number;
            rejected?: number;
            rendering_failed?: number;
            delayed?: number;
            suppressed?: number;
            canceled?: number;
            acceptance_unknown?: number;
            simulated?: number;
        };
    };
    delivery: CampaignDelivery;
    sendEstimate: CampaignSendEstimate;
};

/**
 * Drafts may omit sender, subject, content and audience until review or send, except that domain-restricted keys must supply a From address on one of their domains. Content is block HTML (see html); the same form is what the dashboard composer reads and writes, so people and agents edit one document. Simple {{name}} personalization works in text and quoted href/alt attributes; values are HTML-escaped and rendered URLs are validated. Durable campaign preparation is bounded and runs in background jobs.
 */
export type CampaignDraft = {
    name: string;
    from?: string | '';
    fromName?: string;
    /**
     * Optional preheader text. Inserted as escaped hidden text into each outgoing HTML snapshot; draft HTML is unchanged. When set, supply HTML without its own duplicate preheader.
     */
    previewText?: string;
    replyTo?: Array<string>;
    region: string;
    /**
     * Regional MX only. False follows the From domain; the displayed region is a hint. A supplied region on create or a changed region on edit pins it. To unpin, pass false and omit region.
     */
    regionPinned?: boolean;
    subject?: string | '';
    /**
     * IDs of files uploaded first (uploadAttachment). One file is at most 8 MiB decoded when sent as base64 in JSON (POST /v1/attachments), or 25 MiB as raw bytes (POST /v1/attachments/upload, with the name URI-encoded in X-Nightmail-Filename and the type in Content-Type). One email carries at most 100 files and 25 MiB of them together, decoded. A workspace keeps at most 100 GiB of uploaded files. For anything larger, link to the file from the email.
     */
    attachments?: Array<string>;
    tracking?: boolean;
    audience?: {
        listId?: string;
        segmentId?: string;
        excludeListIds?: Array<string>;
        excludeSegmentIds?: Array<string>;
        /**
         * Send order: contacts whose property equals an earlier value are reviewed and released first; everyone else follows. Useful with paced sending, e.g. { property: "plan", values: ["active", "former"] }.
         */
        priority?: {
            property: string;
            values: Array<string>;
        };
    };
    defaults?: {
        [key: string]: string | number | boolean | null;
    };
    /**
     * Your own unsubscribe or preference page: HTTPS, no user name, password, whitespace or unsubscribe_token parameter, at most 1,000 characters. The footer's Unsubscribe link opens it with unsubscribe_token=<token> added; your page records the opt-out by POSTing that token to /unsubscribe/<token> on this API (idempotent). List-Unsubscribe keeps this API's one-click address, which records the opt-out itself and, opened in a browser, confirms it and then continues to your page. Omit to use the hosted page.
     */
    unsubscribePageUrl?: string;
    /**
     * The topic the campaign is about (listTopics): it skips contacts who opted out of it, and its one-click unsubscribe opts out of this topic only. Not on a required notice.
     */
    topicId?: string;
    /**
     * A required notice: a message every recipient must get whatever their marketing choice, such as a change to terms, prices or taxes, never a promotion. It goes to everyone in the audience who is not suppressed, people who unsubscribed from marketing included, without an Unsubscribe link or List-Unsubscribe header, and is paced, limited and paused like any campaign. Only where an operator turned required notices on for the workspace (requiredNotices in getWorkspaceSettings); 403 REQUIRED_NOTICES_OFF otherwise. Sending or scheduling one needs confirmRequiredNotice. Turned off later, a launched notice pauses before releasing anyone more (pause reason REQUIRED_NOTICES_OFF) and is resumed or rescheduled only once they are on again. Resumed after a list-probe quarantine, it goes on to everyone captured for it (never deliveredOnly).
     */
    requiredNotice?: boolean;
    html?: string;
};

/**
 * The current launch: null until the campaign is sent or scheduled, and cleared by a new revision.
 */
export type CampaignDelivery = {
    /**
     * Fixed recipient count once the audience is frozen (recipients expected while a large audience is being captured).
     */
    total: number;
    /**
     * Recipients whose message was validated.
     */
    prepared: number;
    /**
     * Recipients materialized as immutable email records.
     */
    expanded: number;
    /**
     * Recipients canceled before materialization. Materialized cancellations remain in counts.byStatus.canceled.
     */
    canceled: number;
    /**
     * Why the campaign failed or was canceled by the system.
     */
    error: {
        code: string;
        message: string;
    } | null;
    pacing: {
        /**
         * Maximum recipients released per rolling 24-hour window; null means no daily cap.
         */
        perDay: number | null;
        /**
         * Pause automatically when bounce or complaint rates exceed safe thresholds.
         */
        autoPause: boolean;
        /**
         * Maximum fraction of the SES per-second send rate this campaign uses; 1 is the full rate.
         */
        rateShare: number;
        windowStartedAt: string | null;
        /**
         * Recipients released in the current 24-hour window.
         */
        windowExpanded: number;
        /**
         * When the next 24-hour window opens, when a daily cap is set.
         */
        nextWindowAt: string | null;
        /**
         * Sent with the recommended plan: its daily batches (one 24-hour window each; the last repeats). Null otherwise.
         */
        plan: Array<number> | null;
        /**
         * With a plan: the batch the current window releases, from 1.
         */
        batch: number | null;
        /**
         * With a plan whose growth is checked: held on the same batch since the day before it was not healthy; null while it grows.
         */
        held?: {
            since: string;
            /**
             * The batch the plan repeats, from 1.
             */
            batch: number;
            /**
             * What made the last day unhealthy: hard bounces over 3% of at least 100 accepted, complaints over 0.08% (at least 2), or a reply naming a blocklist.
             */
            why: Array<'bounces' | 'complaints' | 'blocklist'>;
            /**
             * What lets the plan open its next batch, in a sentence.
             */
            toGrow: string;
        } | null;
        /**
         * With a plan: its first day's small batch and the wait after it.
         */
        firstBatch?: {
            /**
             * Recipients the first day starts with.
             */
            size: number;
            /**
             * Minutes it then waits for their bounces and rejections before the rest of the day's batch.
             */
            waitMinutes: number;
        } | null;
    };
    /**
     * The consent source confirmed at launch, if any.
     */
    consent: {
        source: string;
        confirmedAt: string;
    } | null;
    pausedAt: string | null;
    pauseReason: {
        code: string;
        message: string;
    } | null;
    /**
     * After a resumed list-probe quarantine: the rest goes only to contacts this workspace delivered to before; the others are counted in canceled. Never for a required notice.
     */
    deliveredOnly: boolean;
    /**
     * Why releasing recipients is currently held, and the best estimate of until when. list_probe: Hosted sent the first recipients (the list probe) and waits for their bounces and complaints before releasing the rest. feedback_lag: releasing is briefly held while priority safety feedback (bounces/complaints) catches up. ramp: a Hosted sender's first large campaigns release in growing hourly steps (sendEstimate.ramp); this hour's step is used up, or its delivery results are still coming in before the next step. link_record: the campaign has no host for its unsubscribe link right now (its workspace's sending is paused, or with own link hosts, its domain's isn't active yet); it continues by itself.
     */
    waiting: {
        reason: 'pacing_window' | 'ses_daily_quota' | 'hosted_daily_quota' | 'list_probe' | 'balance' | 'feedback_lag' | 'ramp' | 'link_record';
        /**
         * When present, the daily pacing window is the shared link allowance, or the link record is held for operator review.
         */
        linkHold?: 'daily_budget' | 'blocklist';
        until: string;
    } | null;
    /**
     * Recipient domains this campaign stopped sending to because its mail there kept bouncing for good (the rest of its recipients there are counted in canceled, are not charged and are not suppressed), oldest first, at most 50. Empty unless the guard is on.
     */
    stoppedDomains?: Array<{
        domain: string;
        stoppedAt: string;
    }>;
    /**
     * Present while a campaign is preparing, sending, or paused when delivery feedback ingestion is at least 2 minutes behind.
     */
    feedbackLag: {
        oldestMs: number;
        lane: 'routine' | 'priority';
    } | null;
} | null;

/**
 * How long sending takes, for a draft or a campaign that has recipients left to release. Null for a finished or canceled campaign; lists leave it out.
 */
export type CampaignSendEstimate = {
    /**
     * Recipients still to release: for a draft, the last audience count (previewCampaignAudience; null before one); once launched, those not released yet.
     */
    recipients: number | null;
    /**
     * The region's send rate the campaign plans at, per second, before its rate share; null until the region's quota was read.
     */
    ratePerSecond: number | null;
    ramp: CampaignRamp;
    /**
     * How long releasing the recipients left takes from when it starts (the campaign's last change, updatedAt, or scheduledAt): from the ramp, the daily cap (pacing.perDay), the rate share and the region's send rate. A draft is estimated without a daily cap at the full rate. An estimate: it assumes clean, prompt feedback and leaves out the list probe's wait, quota holds and other mail sharing the rate. Null when it cannot be told (no audience count or send rate yet).
     */
    seconds: number | null;
    /**
     * A launched campaign: when its last recipient is expected to be released, as of its last change (updatedAt or scheduledAt, plus seconds). Null for a draft, while paused or failed, or when it cannot be told.
     */
    finishAt: string | null;
} | null;

/**
 * Where the campaign is on the ramp. A Hosted sender's first large campaigns release in hourly steps that grow (1,000 an hour at first), moving to the next step once an hour at this one went out and its delivery results are in and clean; more than 3% bounces or more than 0.08% complaints (at least 2) in a step pause the campaign. The first step not already proven by the workspace's largest clean marketing hour of the last 30 days is where it starts, so an established sender skips it. Null when no ramp applies (self-hosted, your own AWS account, simulated mail, an established sender, or past the last step). Transactional mail never waits for it.
 */
export type CampaignRamp = {
    /**
     * The step the campaign releases at, from 1.
     */
    step: number;
    /**
     * How many steps the ramp has; past the last one only the other limits apply.
     */
    steps: number;
    /**
     * Most recipients this step releases in its hour.
     */
    ceilingPerHour: number;
    /**
     * When this step's hour started: its first release. Null before it.
     */
    startedAt: string | null;
    /**
     * Recipients released since this step's hour started.
     */
    released: number;
} | null;

export type CreateCampaignInput = {
    name: string;
    from?: string | '';
    fromName?: string;
    /**
     * Optional preheader text. Inserted as escaped hidden text into each outgoing HTML snapshot; draft HTML is unchanged. When set, supply HTML without its own duplicate preheader.
     */
    previewText?: string;
    replyTo?: Array<string>;
    /**
     * Defaults to the installation region. With regional MX delivery, omitting region follows the From domain.
     */
    region?: string;
    /**
     * Regional MX only. False follows the From domain; the displayed region is a hint. A supplied region on create or a changed region on edit pins it. To unpin, pass false and omit region.
     */
    regionPinned?: boolean;
    subject?: string | '';
    /**
     * IDs of files uploaded first (uploadAttachment). One file is at most 8 MiB decoded when sent as base64 in JSON (POST /v1/attachments), or 25 MiB as raw bytes (POST /v1/attachments/upload, with the name URI-encoded in X-Nightmail-Filename and the type in Content-Type). One email carries at most 100 files and 25 MiB of them together, decoded. A workspace keeps at most 100 GiB of uploaded files. For anything larger, link to the file from the email.
     */
    attachments?: Array<string>;
    tracking?: boolean;
    audience?: {
        listId?: string;
        segmentId?: string;
        excludeListIds?: Array<string>;
        excludeSegmentIds?: Array<string>;
        /**
         * Send order: contacts whose property equals an earlier value are reviewed and released first; everyone else follows. Useful with paced sending, e.g. { property: "plan", values: ["active", "former"] }.
         */
        priority?: {
            property: string;
            values: Array<string>;
        };
    };
    /**
     * Up to 100 key/value pairs, at most 64 KiB of JSON total.
     */
    defaults?: {
        [key: string]: string | number | boolean | null;
    };
    /**
     * Your own unsubscribe or preference page: HTTPS, no user name, password, whitespace or unsubscribe_token parameter, at most 1,000 characters. The footer's Unsubscribe link opens it with unsubscribe_token=<token> added; your page records the opt-out by POSTing that token to /unsubscribe/<token> on this API (idempotent). List-Unsubscribe keeps this API's one-click address, which records the opt-out itself and, opened in a browser, confirms it and then continues to your page. Omit to use the hosted page.
     */
    unsubscribePageUrl?: string;
    /**
     * The topic the campaign is about (listTopics): it skips contacts who opted out of it, and its one-click unsubscribe opts out of this topic only. Not on a required notice.
     */
    topicId?: string;
    /**
     * A required notice: a message every recipient must get whatever their marketing choice, such as a change to terms, prices or taxes, never a promotion. It goes to everyone in the audience who is not suppressed, people who unsubscribed from marketing included, without an Unsubscribe link or List-Unsubscribe header, and is paced, limited and paused like any campaign. Only where an operator turned required notices on for the workspace (requiredNotices in getWorkspaceSettings); 403 REQUIRED_NOTICES_OFF otherwise. Sending or scheduling one needs confirmRequiredNotice. Turned off later, a launched notice pauses before releasing anyone more (pause reason REQUIRED_NOTICES_OFF) and is resumed or rescheduled only once they are on again. Resumed after a list-probe quarantine, it goes on to everyone captured for it (never deliveredOnly).
     */
    requiredNotice?: boolean;
    /**
     * Block HTML: h1-h3, p, ul/ol, blockquote, pre>code, hr, img, buttons, columns and styled sections with inline formatting. A constrained email-safe style attribute supports color, typography, spacing, borders, radius and dimensions; arbitrary CSS remains rejected. No wrappers, tables, class or id. Call getContentGuide in MCP or GET /v1/campaign-content-guide for the full vocabulary and examples.
     */
    html?: string;
    /**
     * Copies the active published revision of this global campaign template into a new independent campaign draft.
     */
    templateId?: string;
};

/**
 * Campaign list metadata only. Fetch GET /v1/campaigns/{id} for the complete draft before editing or sending. Content, defaults, attachments and audience exclusions are intentionally omitted.
 */
export type CampaignSummary = {
    id: string;
    /**
     * Dashboard URL for opening this campaign. Drafts open in the editor; launched campaigns open in review.
     */
    url: string;
    revision: number;
    sourceTemplateId: string | null;
    sourceTemplateRevision: number | null;
    /**
     * draft: editable. preparing: the audience is being frozen (for large lists) and every message is being validated in the background. scheduled: validated and waiting for scheduledAt. sending: recipients are being released into the dispatch queue. paused: releasing stopped by the user or the health check; queued mail still dispatches. done: every recipient was released and dispatched. failed: capture, preparation or releasing failed (delivery.error); edit or launch again. canceled: terminal.
     */
    state: 'draft' | 'preparing' | 'scheduled' | 'sending' | 'paused' | 'done' | 'failed' | 'canceled';
    scheduledAt: string | null;
    archivedAt: string | null;
    createdAt: string;
    updatedAt: string;
    /**
     * Counts of immutable campaign email records grouped by their current status, not cumulative provider events or delivery rates. Drafts with no queued emails have zero counts.
     */
    counts: {
        total: number;
        byStatus: {
            queued?: number;
            attempting?: number;
            accepted?: number;
            sent?: number;
            delivered?: number;
            bounced?: number;
            complained?: number;
            rejected?: number;
            rendering_failed?: number;
            delayed?: number;
            suppressed?: number;
            canceled?: number;
            acceptance_unknown?: number;
            simulated?: number;
        };
    };
    delivery: CampaignDelivery;
    draft: CampaignDraftSummary;
    stats: CampaignListStats;
};

export type CampaignDraftSummary = {
    name: string;
    region: string;
    from?: string | '';
    fromName?: string;
    subject?: string | '';
    /**
     * Optional preheader text. Inserted as escaped hidden text into each outgoing HTML snapshot; draft HTML is unchanged. When set, supply HTML without its own duplicate preheader.
     */
    previewText?: string;
    audience?: {
        listId?: string;
        segmentId?: string;
    };
};

/**
 * The campaign’s last stored count: the totals getCampaignStats reported when it was taken (computedAt). Null when it has none. Listing never counts emails or events; listing with listId starts a count for finished campaigns whose figures are missing or stale, so they appear on a later read.
 */
export type CampaignListStats = {
    tracking: boolean;
    accepted: number;
    delivered: number;
    opened: number;
    clicked: number;
    /**
     * When the count was taken.
     */
    computedAt: string;
} | null;

/**
 * Lifetime campaign statistics, with no date cutoff or pagination. Done means dispatch finished, not delivery finished. Feedback is asynchronous; missing engagement does not prove nobody read or clicked. Simulated outcomes are never evidence of real delivery.
 */
export type CampaignStats = {
    id: string;
    name: string;
    /**
     * draft: editable. preparing: the audience is being frozen (for large lists) and every message is being validated in the background. scheduled: validated and waiting for scheduledAt. sending: recipients are being released into the dispatch queue. paused: releasing stopped by the user or the health check; queued mail still dispatches. done: every recipient was released and dispatched. failed: capture, preparation or releasing failed (delivery.error); edit or launch again. canceled: terminal.
     */
    state: 'draft' | 'preparing' | 'scheduled' | 'sending' | 'paused' | 'done' | 'failed' | 'canceled';
    tracking: boolean;
    /**
     * Counts of immutable campaign email records grouped by their current status, not cumulative provider events or delivery rates. Drafts with no queued emails have zero counts.
     */
    counts: {
        total: number;
        byStatus: {
            queued?: number;
            attempting?: number;
            accepted?: number;
            sent?: number;
            delivered?: number;
            bounced?: number;
            complained?: number;
            rejected?: number;
            rendering_failed?: number;
            delayed?: number;
            suppressed?: number;
            canceled?: number;
            acceptance_unknown?: number;
            simulated?: number;
        };
    };
    delivery: CampaignDelivery;
    /**
     * Lifetime distinct email counts from current state and stored events; outcomes overlap. Accepted excludes simulated mail; other outcomes include simulated events for simulated mail. Opens and clicks include bots and privacy proxies. Failed means rejected or rendering failed; suppressed, canceled and uncertain mail remain in counts.byStatus.
     */
    totals: {
        accepted: number;
        delivered: number;
        bounced: number;
        complained: number;
        opened: number;
        clicked: number;
        failed: number;
        deliveryDelayed: number;
        simulated: number;
    };
    rates: {
        /**
         * Delivered / accepted. Receiving-server acceptance, not inbox placement.
         */
        delivery: {
            /**
             * Fraction, not percent. Both counts exclude simulated emails. Null when the denominator is zero or engagement tracking is disabled. Not clamped: delayed feedback can temporarily make outcomes exceed the denominator.
             */
            value: number | null;
            numerator: number;
            denominator: number;
        };
        /**
         * Bounced / accepted.
         */
        bounce: {
            /**
             * Fraction, not percent. Both counts exclude simulated emails. Null when the denominator is zero or engagement tracking is disabled. Not clamped: delayed feedback can temporarily make outcomes exceed the denominator.
             */
            value: number | null;
            numerator: number;
            denominator: number;
        };
        /**
         * Complained / accepted.
         */
        complaint: {
            /**
             * Fraction, not percent. Both counts exclude simulated emails. Null when the denominator is zero or engagement tracking is disabled. Not clamped: delayed feedback can temporarily make outcomes exceed the denominator.
             */
            value: number | null;
            numerator: number;
            denominator: number;
        };
        /**
         * Unique opened emails / delivered.
         */
        open: {
            /**
             * Fraction, not percent. Both counts exclude simulated emails. Null when the denominator is zero or engagement tracking is disabled. Not clamped: delayed feedback can temporarily make outcomes exceed the denominator.
             */
            value: number | null;
            numerator: number;
            denominator: number;
        };
        /**
         * Unique clicked emails / delivered, not click-to-open rate.
         */
        click: {
            /**
             * Fraction, not percent. Both counts exclude simulated emails. Null when the denominator is zero or engagement tracking is disabled. Not clamped: delayed feedback can temporarily make outcomes exceed the denominator.
             */
            value: number | null;
            numerator: number;
            denominator: number;
        };
    };
    /**
     * When counts, totals and rates were counted: they include every change made before then. state and delivery are always current.
     */
    computedAt: string;
};

export type CampaignContentGuide = {
    format: 'markdown';
    markdown: string;
};

export type CampaignPreview = {
    /**
     * Complete rendered email document; empty when the draft has no content.
     */
    html: string;
    text: string;
};

/**
 * Live counts for the saved audience: matched contacts, those eligible for marketing, and the suppressed, unsubscribed or risky remainder. For a required notice everyone not suppressed or risky is eligible and unsubscribed is 0. Read-only; sending freezes its own snapshot and rechecks consent at dispatch.
 */
export type CampaignAudienceCounts = {
    matched: number;
    eligible: number;
    suppressed: number;
    unsubscribed: number;
    /**
     * Contacts who could receive it but are flagged as risky (a disposable inbox, a mistyped provider, a role address, an address known to be undeliverable): the send skips them. Not in eligible.
     */
    risky: number;
    riskyByReason: {
        invalid: number;
        disposable: number;
        typo_domain: number;
        role: number;
        dead: number;
        no_mail_domain: number;
    };
    /**
     * With a topic: the subscribed contacts it leaves out (who opted out of it, or for a topic only people who opt in get, who didn’t). Counted in unsubscribed, not in eligible.
     */
    topicExcluded?: number;
    /**
     * The topic’s effect on this list couldn’t be counted in time: eligible and topicExcluded are estimated from the workspace’s choices about the topic. Sending counts it exactly.
     */
    approximate?: true;
    /**
     * With readiness=true: the send review of a marketing campaign with a sender; null for a required notice or a draft without a sender.
     */
    readiness?: {
        /**
         * ready: send as you like. ramp_recommended: the plan is suggested. ramp_required: a Hosted send this large, from a new domain or far above anything its domain has sent, goes out with the plan (pacing.plan "recommended"), a daily limit no larger than its first day, or a confirmed consent source (consent); 422 RAMP_REQUIRED otherwise.
         */
        verdict: 'ready' | 'ramp_recommended' | 'ramp_required';
        /**
         * Why, in one or two plain sentences, when a ramp is recommended or required.
         */
        summary: string | null;
        /**
         * The findings behind the verdict in the original codes, one per code: a newly registered domain, one new here and a new link domain read NEW_DOMAIN, a jump over the usual day SIZE_JUMP; blocklist findings appear only in findings. Prefer findings.
         */
        reasons: Array<{
            code: 'NEW_DOMAIN' | 'SIZE_JUMP' | 'NO_HISTORY' | 'RISKY_LIST' | 'NEVER_MAILED' | 'NO_DMARC' | 'BOUNCES' | 'COMPLAINTS';
            message: string;
        }>;
        /**
         * Every finding behind the verdict, with its own code: NEW_REGISTRATION (registered recently, from public registry data), NEW_HERE (registered long ago, new to this workspace), NEW_DOMAIN (added recently, registration not known), USUAL_JUMP, NEW_LINK_DOMAIN, BLOCKLISTED_BEFORE (an earlier send drew replies naming a blocklist and none has finished without since), BLOCKLIST_UNCOUNTED (a recent send's blocklist replies aren't counted yet, so it isn't taken for clean), and the original codes.
         */
        findings?: Array<{
            code: 'NEW_DOMAIN' | 'SIZE_JUMP' | 'NO_HISTORY' | 'RISKY_LIST' | 'NEVER_MAILED' | 'NO_DMARC' | 'BOUNCES' | 'COMPLAINTS' | 'NEW_REGISTRATION' | 'NEW_HERE' | 'USUAL_JUMP' | 'NEW_LINK_DOMAIN' | 'BLOCKLISTED_BEFORE' | 'BLOCKLIST_UNCOUNTED';
            message: string;
        }>;
        /**
         * Present when part of the review couldn't be worked out just now (sizing the plan): what was left out, in a sentence. The review is then the one without that part, and its verdict is at least ramp_recommended.
         */
        unavailable?: string;
        domain: {
            name: string;
            /**
             * When the From domain (or the domain it is under) was added to this workspace.
             */
            firstSeenAt: string | null;
            /**
             * Days since it was added to this workspace: its history here, not its age.
             */
            ageDays: number | null;
            /**
             * When its registrable domain was registered (YYYY-MM-DD), from public registry data; null when not known (never taken for old).
             */
            registeredAt?: string | null;
            /**
             * Days since registeredAt; null when not known.
             */
            registeredDays?: number | null;
            linkDomain?: {
                /**
                 * The registrable domain the links go on, when it is not the From domain's.
                 */
                name: string;
                registeredAt: string | null;
                registeredDays: number | null;
            } | null;
            /**
             * The DMARC policy last observed; null when not checked yet.
             */
            dmarc: 'reject' | 'quarantine' | 'none' | 'missing' | 'invalid' | null;
            /**
             * The custom MAIL FROM domain (aligned SPF).
             */
            mailFrom: 'verified' | 'pending' | 'failed' | 'not_configured';
            /**
             * This campaign shares the link domain’s daily sending allowance.
             */
            sharedLinkPacing?: boolean;
            /**
             * Kept for compatibility, always not_configured: ownLinkHost and linkOrigin say where the links go.
             */
            linkHost: 'not_configured';
            /**
             * The domain's own link host, when this workspace has them; null without one.
             */
            ownLinkHost: {
                /**
                 * links.<domain>.
                 */
                hostname: string;
                /**
                 * true: the links go there. false: it isn’t set up yet, so they go on linkOrigin (the link domain) meanwhile.
                 */
                active: boolean;
            } | null;
            /**
             * Where this campaign's links (its unsubscribe link, the text part's, List-Unsubscribe and linked images) go if it launches now: the domain's own link host when active, else the link domain (Hosted) or this installation's own origin. Null when the launch would be refused for want of one (the workspace's sending is paused, or no link host for the domain). A launch on the link domain moves to the domain's own host for the copies made once that is active.
             */
            linkOrigin: string | null;
        };
        history: {
            /**
             * Every kind of mail the workspace sent; largestSend counts campaigns.
             */
            workspace: {
                /**
                 * Most recipients SES accepted from one campaign in the last 90 days.
                 */
                largestSend: number;
                /**
                 * When this workspace first had mail accepted (workspace history only); null with none.
                 */
                firstSentAt?: string | null;
                /**
                 * The usual day: the median of the mail accepted on the days it sent in the last 14 days (workspace history only); 0 with none.
                 */
                usualDay?: number;
                /**
                 * Recipients SES accepted in the last 30 days.
                 */
                sent: number;
                /**
                 * Hard bounces ÷ accepted over the last 30 days; null with nothing sent.
                 */
                bounceRate: number | null;
                /**
                 * Complaints ÷ accepted over the last 30 days; null with nothing sent.
                 */
                complaintRate: number | null;
            };
            /**
             * Campaigns from this From domain.
             */
            domain: {
                /**
                 * Most recipients SES accepted from one campaign in the last 90 days.
                 */
                largestSend: number;
                /**
                 * When this workspace first had mail accepted (workspace history only); null with none.
                 */
                firstSentAt?: string | null;
                /**
                 * The usual day: the median of the mail accepted on the days it sent in the last 14 days (workspace history only); 0 with none.
                 */
                usualDay?: number;
                /**
                 * Recipients SES accepted in the last 30 days.
                 */
                sent: number;
                /**
                 * Hard bounces ÷ accepted over the last 30 days; null with nothing sent.
                 */
                bounceRate: number | null;
                /**
                 * Complaints ÷ accepted over the last 30 days; null with nothing sent.
                 */
                complaintRate: number | null;
            };
        };
        list: {
            recipients: number;
            /**
             * Risky contacts the send skips.
             */
            risky: number;
            /**
             * Recipients who joined the list since it was last sent to (or ever, when it never was) and have no open or click on record; null when counting took too long.
             */
            neverMailed: number | null;
            createdAt: string | null;
            /**
             * When a campaign last went to this list.
             */
            lastSentAt: string | null;
            lastImport: {
                at: string;
                contacts: number;
                /**
                 * The consent evidence it was imported with, if any.
                 */
                consent: string | null;
            } | null;
        };
        /**
         * This send ÷ the largest campaign its domain sent in the last 90 days; null without one.
         */
        sizeJump: number | null;
        /**
         * This send ÷ the workspace's usual day (history.workspace.usualDay); null without one.
         */
        usualJump?: number | null;
        /**
         * The recommended daily batches; null when one day covers everyone.
         */
        plan: {
            /**
             * Recipients per day, in order: one batch a day, the most engaged first and never-mailed last.
             */
            batches: Array<number>;
            /**
             * The first day's small batch and wait, inside its batch; null when the first day is small already.
             */
            firstBatch?: {
                /**
                 * Recipients the first day starts with.
                 */
                size: number;
                /**
                 * Minutes it then waits for their bounces and rejections before the rest of the day's batch.
                 */
                waitMinutes: number;
            } | null;
            /**
             * How long the plan takes from its start, the hourly ramp included.
             */
            seconds: number | null;
        } | null;
        required: {
            /**
             * Kept as it was: a newly registered domain reads NEW_DOMAIN and a blocklist SIZE_JUMP. reason says which.
             */
            by: 'NEW_DOMAIN' | 'SIZE_JUMP';
            /**
             * What requires the ramp. BLOCKLISTED: mail from this From domain or with these links drew replies naming a blocklist and no send has finished without any since; a consent confirmation does not waive it.
             */
            reason?: 'NEW_REGISTRATION' | 'BLOCKLISTED' | 'NEW_DOMAIN' | 'SIZE_JUMP';
            /**
             * The largest daily limit that counts as a ramp: the plan's first day.
             */
            maxPerDay: number;
        } | null;
    } | null;
};

