export type InboxMessage = {
    id: string;
    threadId: string;
    /**
     * Pass as after to continue after this message.
     */
    cursor: string;
    /**
     * The claimed sender. Check auth before trusting it.
     */
    from: {
        name: string | null;
        address: string;
    };
    /**
     * Addresses in the To header (at most 20 on list pages, up to 100 on getInboxMessage).
     */
    to: Array<{
        name: string | null;
        address: string;
    }>;
    /**
     * Total addresses in the To header (may exceed to.length when shortened).
     */
    toCount: number;
    subject: string;
    snippet: string;
    /**
     * When the sending server handed it over (SES received it).
     */
    receivedAt: string;
    /**
     * When the write that stored it in Nightmail committed, on the clock servedAt uses.
     */
    storedAt: string;
    /**
     * Milliseconds from the receipt reaching Nightmail to storedAt: fetching, parsing, routing and storing the message. Null for mail that came another way (simulated, sent, copied).
     */
    processingMs: number | null;
    read: boolean;
    flags: Array<'flagged' | 'answered' | 'draft' | 'forwarded' | 'junk' | 'notJunk' | 'mdnSent'>;
    labels: Array<string>;
    folders: Array<{
        folder: 'inbox' | 'sent' | 'junk' | 'archive' | 'trash';
        uid: number;
        uidValidity: number;
        modseq: string;
        deleted: boolean;
    }>;
    additionalFolders: Array<{
        /**
         * Stable folder locator: a built-in role or a custom folder ID.
         */
        folder: 'inbox' | 'sent' | 'junk' | 'archive' | 'trash' | 'drafts' | string;
        uid: number;
        uidValidity: number;
        modseq: string;
        deleted: boolean;
    }>;
    modseq: string;
    uid: number | null;
    uidValidity: number | null;
    /**
     * SES judged this message spam.
     */
    junk: boolean;
    /**
     * null when delivered; quota or expired when stored but held.
     */
    held: 'quota' | 'expired' | null;
    attachmentCount: number;
    /**
     * SES verdicts for the sender: PASS, FAIL, GRAY or NONE.
     */
    auth: {
        spf?: string;
        dkim?: string;
        dmarc?: string;
    };
    /**
     * Created by POST /v1/inboxes/{id}/simulate, not received over SMTP.
     */
    simulated: boolean;
    /**
     * Best-effort detection of hidden, styled or invisible content. False does not guarantee visibility.
     */
    hiddenContent: boolean;
    /**
     * Filled when requested with extract.
     */
    extract: {
        /**
         * Up to 5 one-time codes near words like code, verify or OTP, in the best-effort text projection.
         */
        codes: Array<string>;
        /**
         * Up to 20 http(s) links from visible text. Nothing is fetched.
         */
        links: Array<{
            text: string;
            href: string;
            /**
             * The link text names a different host than the href.
             */
            mismatch: boolean;
        }>;
    };
};

