export type BillingSummary = {
    /**
     * off: nothing is metered for billing. shadow: usage is recorded and priced but nothing is charged. enforce: usage is taken from the balance hourly.
     */
    enforcement: 'off' | 'shadow' | 'enforce';
    /**
     * prepaid: usage is taken from the balance. exempt: the workspace is free (see freePlan).
     */
    mode: 'prepaid' | 'exempt';
    state: {
        /**
         * paused: sends get 402 BALANCE_EXHAUSTED until credit is added.
         */
        sending: 'ok' | 'low' | 'paused';
        /**
         * grace: the balance is below $0 and received mail is still accepted until grace.receiveHoldAt; held: new received mail is stored but not delivered until a top-up. While the installation doesn’t hold received mail, receiving stays ok.
         */
        receiving: 'ok' | 'grace' | 'held';
        autoRecharge: 'off' | 'on' | 'pending' | 'failed' | 'capped';
    };
    /**
     * Null unless the caller is an owner or admin session, or a manage key or grant.
     */
    balance: {
        paid: MicroCents;
        promo: MicroCents & unknown;
        unsettled: MicroCents & unknown;
        available: MicroCents & unknown;
    } | null;
    free: {
        month: string;
        /**
         * The sent allowance (same as sent), kept for older clients. Each direction has its own allowance: see sent and received.
         */
        emails: {
            limit: number;
            /**
             * Used this month, settled and unsettled.
             */
            used: number;
            left: number;
        };
        /**
         * Free sent emails this month, each recipient counting once. Sends beyond it are charged even while received mail is still free.
         */
        sent: {
            limit: number;
            /**
             * Used this month, settled and unsettled.
             */
            used: number;
            left: number;
        };
        /**
         * Free received messages this month, separate from the sent allowance. Null unless the credential may read every received message (owners, admins and manage credentials), as in GET /v1/usage.
         */
        received: {
            limit: number;
            /**
             * Used this month, settled and unsettled.
             */
            used: number;
            left: number;
        } | null;
        storage: {
            limitBytes: number;
            /**
             * Bytes of received mail older than 90 days.
             */
            agedBytes: string;
        };
    };
    monthToDate: {
        cost: MicroCents & unknown;
    } | null;
    grace: {
        unpaidSince: string | null;
        /**
         * When new received mail starts being held; null when nothing is owed or the installation doesn’t hold received mail.
         */
        receiveHoldAt: string | null;
        writeOffAt: string | null;
    };
    autoRecharge: {
        enabled: boolean;
        thresholdCents: number;
        amountCents: number;
        monthlyCapCents: number;
        monthTotalCents: number;
        /**
         * Why Nightmail turned auto-recharge off (a card decline code, dispute or a removed card).
         */
        disabledReason: string | null;
        pending: boolean;
    } | null;
    paymentMethod: {
        brand: string;
        last4: string;
        expMonth: number;
        expYear: number;
    } | null;
    prices: {
        /**
         * USD per 1,000 emails, sent (per recipient) or received (per message).
         */
        emailPerThousand: string;
        /**
         * Deprecated: AI decisions are free, so this is always "0.00".
         *
         * @deprecated
         */
        decisionPerThousand: string;
        /**
         * Deprecated: decisionPerThousand, always "0.00".
         *
         * @deprecated
         */
        omenPerThousand: string;
        /**
         * USD per GB-month for received mail older than 90 days, beyond the free GB.
         */
        storagePerGbMonth: string;
        /**
         * The sent allowance (same as freeSentEmails), kept for older clients. Each direction has its own allowance, counted separately (freeSentEmails, freeReceivedEmails).
         */
        freeEmails: number;
        /**
         * Sent emails (each recipient) free each calendar month (UTC).
         */
        freeSentEmails: number;
        /**
         * Received messages free each calendar month (UTC), separate from the sent allowance.
         */
        freeReceivedEmails: number;
        freeStorageBytes: number;
        topUpMinCents: number;
        currency: 'USD';
    };
    /**
     * Where a person adds credit.
     */
    topUpUrl: string;
    /**
     * Set when Anomaly made this workspace free (mode exempt): nothing is charged and sending never pauses for the balance. Usage is still measured, and monthToDate shows what it would cost.
     */
    freePlan: {
        /**
         * When the free plan ends; null: no end date.
         */
        until: string | null;
    } | null;
};

/**
 * Integer micro-cents (1¢ = 1,000,000) as a string.
 */
export type MicroCents = string;

export type BillingUsagePoint = {
    /**
     * Start of the period, UTC.
     */
    start: string;
    meter: 'send' | 'receive' | 'omen' | 'storage' | 'byo_send' | 'byo_receive';
    /**
     * send: recipients; receive: messages; omen: emails checked by AI decisions, which are free (the meter keeps its name from before the rename); storage: billable byte-days beyond the free GB; byo_*: reported only, $0.
     */
    quantity: string;
};

export type BillingLedgerEntry = {
    id: string;
    at: string;
    kind: 'topup' | 'usage' | 'grant' | 'refund_hold' | 'refund_release' | 'dispute' | 'dispute_reversal' | 'write_off' | 'adjustment' | 'expire';
    amount: MicroCents & unknown;
    paid: MicroCents;
    promo: MicroCents;
    balanceAfter: MicroCents & unknown;
    description: string;
    detail: {
        [key: string]: unknown;
    };
    paymentId: string | null;
    invoiceUrl: string | null;
    /**
     * For a top-up: when its remaining credit expires, 12 months after purchase. Unused credit is not refundable.
     */
    expiresAt: string | null;
};

