    id: string;
    at: string;
    kind: 'checkout' | 'saved_card' | 'recharge' | 'setup';
    status: 'created' | 'pending' | 'requires_action' | 'succeeded' | 'failed' | 'canceled' | 'expired';
    /**
     * Credit bought, excluding tax.
     */
    amountCents: number;
    taxCents: number | null;
