export type ListLogsData = {
    body?: never;
    path?: never;
    query?: {
        cursor?: string;
        limit?: number;
        direction?: 'all' | 'sent' | 'received';
        /**
         * At least 3 characters: a shorter term is refused with 422 VALIDATION_FAILED. Sent mail: a literal, case-insensitive substring of the sender, recipients, subject or IDs. Received mail: a full-text match on sender, recipients, subject and body.
         */
        search?: string;
        /**
         * A sent-mail status lists sent mail only. received lists received mail that is not flagged as spam; spam lists received mail flagged as spam (spam is visible to administrators only, so dashboard members get none). Either leaves sent mail out, and is refused (403) to credentials that cannot read received mail, like direction=received.
         */
        status?: 'queued' | 'attempting' | 'accepted' | 'sent' | 'delivered' | 'bounced' | 'complained' | 'rejected' | 'rendering_failed' | 'delayed' | 'suppressed' | 'canceled' | 'acceptance_unknown' | 'simulated' | 'scheduled' | 'received' | 'spam';
        /**
         * Sent mail only; received mail is left out when set.
         */
        kind?: 'transactional' | 'marketing';
        /**
         * Sent mail only; received mail is left out when set.
         */
        campaignId?: string;
        region?: string;
        /**
         * Mail created (sent) or received at or after this instant.
         */
        from?: string;
        /**
         * Mail created (sent) or received before this instant.
         */
        to?: string;
        /**
         * true adds counts: how many emails match each status and kind for these filters between from and to (all retained mail without them), whatever the cursor and limit. Counts that take longer than 2 seconds are refused with 422 READ_TOO_LARGE: narrow from and to.
         */
        counts?: 'true' | 'false';
    };
    url: '/v1/logs';
};

